import { Drawer as DrawerPrimitive } from "vaul";

import { cn } from "@/lib/utils";

/**
 * On iOS, vaul scroll-locks the page with `position: fixed` on `<body>` and restores
 * the offset itself — but that restore frequently lands on 0, dumping the user at the
 * top of the page when the drawer closes. Track the offset ourselves and reassert it
 * for a few frames after close so it wins against vaul's own restore.
 */
function useScrollRestoreOnClose(isOpen: boolean) {
  const scrollY = React.useRef(0);
  const isOpenRef = React.useRef(isOpen);
  const wasOpen = React.useRef(false);

  // Written during render so it is already current when vaul's layout effect locks scroll.
  isOpenRef.current = isOpen;

  React.useEffect(() => {
    const onScroll = () => {
      if (!isOpenRef.current) {
        scrollY.current = window.scrollY;
      }
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  React.useEffect(() => {
    if (isOpen) {
      wasOpen.current = true;
      return;
    }
    if (!wasOpen.current) return;
    wasOpen.current = false;

    const target = scrollY.current;
    if (target === 0) return;

    let frame = 0;
    let handle = 0;
    const restore = () => {
      if (Math.abs(window.scrollY - target) > 1) {
        window.scrollTo(0, target);
      }
      if (++frame < 6) {
        handle = requestAnimationFrame(restore);
      }
    };
    handle = requestAnimationFrame(restore);

    return () => cancelAnimationFrame(handle);
  }, [isOpen]);
}

function Drawer({
  open,
  defaultOpen,
  onOpenChange,
  ...props
}: React.ComponentProps<typeof DrawerPrimitive.Root>) {
  const [internalOpen, setInternalOpen] = React.useState(defaultOpen ?? false);
  useScrollRestoreOnClose(open ?? internalOpen);

  return (
    <DrawerPrimitive.Root
      data-slot="drawer"
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={(nextOpen) => {
        setInternalOpen(nextOpen);
        onOpenChange?.(nextOpen);
      }}
      {...props}
    />
  );
}"}

